```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_rw};

struct Node;

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved set kept).
fn encode_query(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len() * 3);
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch (approved grant extension). The result is not used and
        // a transport failure is tolerated, so the node's output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&published.date)
        );
        let _ = http_client::fetch(&url);

        // Mark every considered item as seen, but only once the digest was
        // actually published, so unpublished items are reconsidered next run.
        let mut recorded: u32 = 0;
        if published.published {
            let mut done: Vec<&str> = Vec::with_capacity(published.considered.len());
            for id in published.considered.iter() {
                let id = id.as_str();
                if id.is_empty() || done.contains(&id) {
                    continue;
                }
                state_rw::put(id, &published.date);
                done.push(id);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

